<?php
require_once __DIR__.'/vehicles.php'; require_once __DIR__.'/criminals.php';
function rangers_general_fine_view(array $f):array{$reason=strtoupper($f['reason']??$f['sanction']??'');$date=substr((string)($f['fine_date']??$f['issued_at']??''),0,10);$externalId=trim((string)($f['external_multa_id']??''));return ['id'=>$externalId!==''?'PDA-'.$externalId:$f['fine_code'],'storage_id'=>$f['storage_id'],'nombre'=>$f['person_name'],'agente'=>$f['issued_by_name']??'','razon'=>$reason,'sancion'=>$reason,'fecha'=>$date,'valor'=>rangers_format_currency((float)$f['amount']),'abonada'=>!empty($f['is_paid'])?'ABONADA':'PENDIENTE','external_multa_id'=>$externalId,'review_status'=>$externalId!==''?'REVISADA':'REGISTRO INTERNO'];}
function rangers_fetch_general_fines():array{$x=[];foreach(rangers_firebase_keyed_rows('general_fines') as $key=>$fine)$x[]=['storage_id'=>$key]+$fine;usort($x,fn($a,$b)=>strcmp($b['issued_at']??'',$a['issued_at']??''));return array_map(fn($f)=>rangers_general_fine_view($f),$x);}
function rangers_create_general_fine(array $d,mixed $uid,string $agent):array{$amount=rangers_parse_currency($d['valor']??'0');$reason=strtoupper(trim($d['razon']??$d['sancion']??''));$fine=['fine_code'=>'MG-'.date('ymdHis').random_int(10,99),'person_name'=>strtoupper(trim($d['nombre']??'')),'issued_by_user_id'=>$uid,'issued_by_name'=>strtoupper(trim($agent)),'reason'=>$reason,'sanction'=>$reason,'amount'=>$amount,'fine_date'=>trim((string)($d['fecha']??date('Y-m-d'))),'is_paid'=>strtoupper(trim((string)($d['abonada']??'NO')))==='SI','issued_at'=>date('Y-m-d H:i:s')];foreach(['external_multa_id','external_character_id','nacionalidad','reviewed_at'] as $key)if(isset($d[$key])&&$d[$key]!=='')$fine[$key]=(string)$d[$key];$storageId=rangers_new_id();rangers_firebase_set('general_fines/'.$storageId,$fine);rangers_sync_general_fine_to_criminal(['nombre'=>$fine['person_name'],'sancion'=>$reason,'valor'=>rangers_format_currency($amount)]);return rangers_general_fine_view(['storage_id'=>$storageId]+$fine);}
function rangers_update_general_fine(string $id,array $d):?array{$fine=rangers_firebase_get('general_fines/'.$id);if(!$fine)throw new RuntimeException('Multa no encontrada.');$reason=strtoupper(trim($d['razon']??$d['sancion']??$fine['reason']??$fine['sanction']??''));rangers_firebase_update('general_fines/'.$id,['person_name'=>strtoupper(trim($d['nombre']??$fine['person_name'])),'issued_by_name'=>strtoupper(trim($d['agente']??$fine['issued_by_name']??'')),'reason'=>$reason,'sanction'=>$reason,'amount'=>rangers_parse_currency((string)($d['valor']??$fine['amount'])),'fine_date'=>trim((string)($d['fecha']??$fine['fine_date']??substr((string)($fine['issued_at']??''),0,10))),'is_paid'=>strtoupper(trim((string)($d['abonada']??(!empty($fine['is_paid'])?'SI':'NO'))))==='SI','updated_at'=>date('Y-m-d H:i:s')]);foreach(rangers_fetch_general_fines() as $item)if($item['storage_id']===$id)return $item;return null;}
function rangers_delete_general_fine(string $id):void{if(!rangers_firebase_get('general_fines/'.$id))throw new RuntimeException('Multa no encontrada.');rangers_firebase_delete('general_fines/'.$id);}
